library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.textio.all;
use ieee.std_logic_textio.all;

use work.feature_pkg.all;
use work.fast_pkg.all;

-- Testbench for fast_response (FAST corner score).
--
-- Vectors: testbenches/vectors.hex, generated by fast_response_generator.py
-- (reference model = OpenCV cornerScore). One vector per line, hex bytes:
--   center  c0..c15 (16 Bresenham-circle pixels)  expected_score.
--
-- Self-checking: drives one vector per cycle and pushes the expected score into
-- a circular queue; a parallel checker compares o_score against the queue head
-- on every o_valid (DUT latency 4). Reports totals and fails (severity failure)
-- if any mismatch.
entity fast_response_tb is
end entity;

architecture sim of fast_response_tb is
    -----------------------------------------------------------------
    -- Test configuration
    -----------------------------------------------------------------
    constant CLK_PERIOD     : time    := 4 ns;   -- 250 MHz
    constant PIPELINE_DEPTH : natural := 4;      -- DUT latency in cycles
    constant QUEUE_MARGIN   : natural := 4;      -- safety factor
    constant QUEUE_DEPTH    : natural := PIPELINE_DEPTH * QUEUE_MARGIN;
    constant DRAIN_CYCLES   : natural := PIPELINE_DEPTH + 4;
    constant VECTOR_FILE    : string  := "testbenches/vectors.hex";

    -----------------------------------------------------------------
    -- DUT signals
    -----------------------------------------------------------------
    signal clk      : std_logic := '0';
    signal rst      : std_logic := '1';
    signal i_valid  : std_logic := '0';
    signal i_center : pixel_t   := (others => '0');
    signal i_circle : circle_t  := (others => (others => '0'));
    signal o_valid  : std_logic;
    signal o_score  : pixel_t;

    -----------------------------------------------------------------
    -- Expected-value circular buffer
    -----------------------------------------------------------------
    type score_queue_t is array (natural range <>) of pixel_t;
    signal exp_queue : score_queue_t(0 to QUEUE_DEPTH-1) := (others => (others => '0'));
    signal exp_wr    : natural := 0;
    signal exp_rd    : natural := 0;

    signal errors    : natural := 0;
    signal checks    : natural := 0;
    signal done      : boolean := false;
begin

    dut : entity work.fast_response
        port map (
            clk => clk, rst => rst,
            i_valid => i_valid, i_center => i_center, i_circle => i_circle,
            o_valid => o_valid, o_score => o_score
        );

    -- Clock
    clk <= not clk after CLK_PERIOD/2 when not done else '0';

    -- Stimulus + expected-value tracking
    stim : process
        file     vec_file : text open read_mode is VECTOR_FILE;
        variable line_in  : line;
        variable hex_v    : std_logic_vector(7 downto 0);
        variable c_var    : pixel_t;
        variable circ_var : circle_t;
        variable exp_var  : pixel_t;
    begin
        rst <= '1';
        wait for 5 * CLK_PERIOD;
        rst <= '0';
        wait until rising_edge(clk);

        while not endfile(vec_file) loop
            readline(vec_file, line_in);

            hread(line_in, hex_v); c_var := unsigned(hex_v);
            for k in 0 to 15 loop
                hread(line_in, hex_v);
                circ_var(k) := unsigned(hex_v);
            end loop;
            hread(line_in, hex_v); exp_var := unsigned(hex_v);

            -- Drive one cycle
            i_center <= c_var;
            i_circle <= circ_var;
            i_valid  <= '1';

            -- Push expected
            exp_queue(exp_wr mod QUEUE_DEPTH) <= exp_var;
            exp_wr <= exp_wr + 1;

            wait until rising_edge(clk);
        end loop;

        i_valid <= '0';

        -- Drain pipeline
        wait for DRAIN_CYCLES * CLK_PERIOD;

        report "Checked " & to_string(checks) &
               " vectors, " & to_string(errors) & " errors.";
        assert errors = 0 report "TEST FAILED" severity failure;
        report "TEST PASSED" severity note;
        done <= true;
        wait;
    end process;

    -- Output checker
    check : process(clk)
        variable expected : pixel_t;
    begin
        if rising_edge(clk) then
            if o_valid = '1' then
                expected := exp_queue(exp_rd mod QUEUE_DEPTH);
                if o_score /= expected then
                    report "MISMATCH at check " & to_string(checks) &
                           ": got " & to_string(o_score) &
                           ", expected " & to_string(expected)
                        severity error;
                    errors <= errors + 1;
                end if;
                checks <= checks + 1;
                exp_rd <= exp_rd + 1;
            end if;
        end if;
    end process;

end architecture;